def maxAreaOfIsland(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = [[False] * C for _ in range(R)]
    best = 0
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 1 and not seen[i][j]:
                area = 0
                st = [(i, j)]
                seen[i][j] = True
                while st:
                    r, c = st.pop()
                    area += 1
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 1 and not seen[nr][nc]:
                            seen[nr][nc] = True
                            st.append((nr, nc))
                best = max(best, area)
    return best

