def maxAreaOfIsland(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    p = list(range(R * C))
    def f(x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 1:
                for di, dj in ((1, 0), (0, 1)):
                    ni, nj = i + di, j + dj
                    if ni < R and nj < C and grid[ni][nj] == 1:
                        p[f(i * C + j)] = f(ni * C + nj)
    cnt = {}
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 1:
                k = f(i * C + j)
                cnt[k] = cnt.get(k, 0) + 1
    return max(cnt.values()) if cnt else 0

