def maxAreaOfIsland(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = [[False] * C for _ in range(R)]
    def dfs(r, c):
        if r < 0 or c < 0 or r >= R or c >= C or grid[r][c] != 1 or seen[r][c]:
            return 0
        seen[r][c] = True
        return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)
    return max([dfs(i, j) for i in range(R) for j in range(C)] or [0])
